/* DELGROSSO Ultimate - Conferme PDF A4 offline senza librerie esterne.
 * Genera una conferma di prenotazione GESTIONALE, non una fattura fiscale.
 * v1.4: logo aziendale integrato nel PDF, dimensioni/posizione verificate.
 */
'use strict';
(function(global){
 const compact=s=>String(s??'').normalize('NFKD').replace(/[\u0300-\u036f]/g,'')
  .replace(/[^\x20-\x7e]/g,' ').replace(/\s+/g,' ').trim();
 const lit=s=>'('+compact(s).replace(/([\\()])/g,'\\$1')+')';
 const LOGO_W=907,LOGO_H=480,LOGO_B64='';
 function seats(book){
  const xs=String(book.posti_selezionati||'').split(',').map(x=>x.trim());
  if(xs.some(x=>!/^[1-9][0-9]*$/.test(x)))throw Error('Posti storici non numerici: verifica la prenotazione');
  const n=xs.map(Number).sort((a,b)=>a-b);
  if(new Set(n).size!==n.length||n.length!==Number(book.posti))throw Error('Posti non riconciliati con il numero di passeggeri');
  return n.join(',');
 }
 function makePdf(book,trip){
  const meta='DG2BOOKING:'+book.id+';SEATS:'+seats(book);
  const commands=[];
  const RGB=(r,g,b)=>`${r.toFixed(3)} ${g.toFixed(3)} ${b.toFixed(3)}`;
  const navy=RGB(.035,.105,.200),blue=RGB(.08,.34,.62),gold=RGB(.97,.67,.13),muted=RGB(.35,.40,.48),soft=RGB(.93,.96,.99);
  const text=(s,x,y,size=11,bold=false,color=navy)=>commands.push(`BT ${color} rg /${bold?'F2':'F1'} ${size} Tf 1 0 0 1 ${x} ${y} Tm ${lit(s)} Tj ET`);
  const rect=(x,y,w,h,color)=>commands.push(`${color} rg ${x} ${y} ${w} ${h} re f`);
  const line=(x1,y1,x2,y2,color=muted)=>commands.push(`${color} RG 0.5 w ${x1} ${y1} m ${x2} ${y2} l S`);
  const logoDrawW=168, logoDrawH=Math.round(logoDrawW*LOGO_H/LOGO_W);
  commands.push(`q ${logoDrawW} 0 0 ${logoDrawH} 42 715 cm /Im1 Do Q`);
  rect(214,772,337,44,navy);
  rect(214,768,337,4,gold);
  text('CONFERMA DI PRENOTAZIONE',228,790,16,true,RGB(1,1,1));
  text('DOCUMENTO GESTIONALE - NON FATTURA',228,776,9,false,RGB(.85,.92,1));
  line(45,690,550,690,RGB(.82,.86,.9));
  text('Riferimento: '+(book.codice||book.id_prenotazione||book.id),45,673,9,false,muted);
  let y=642;
  const row=(label,value)=>{text(label.toUpperCase(),45,y,9,true,blue);text(value||'--',194,y,11,true,navy);y-=31;};
  row('Cliente',book.cliente_nome||book.cliente);
  row('Viaggio',trip.titolo||trip.destinazione);
  row('Destinazione',trip.destinazione);
  row('Data partenza',trip.data_partenza);
  row('Fermata',book.fermata_partenza);
  row('Numero passeggeri',book.posti);
  row('Posti assegnati',seats(book).split(',').join(' - '));
  const euro=x=>Number(x??0).toFixed(2).replace('.',',')+' EUR';
  row('Totale prenotazione',euro(book.totale));
  row('Importo versato',euro(book.pagato));
  row('Residuo da pagare',euro(Math.max(0,Number(book.totale||0)-Number(book.pagato||0))));
  rect(44,170,507,66,soft);
  text('PRESENTARSI AL PUNTO DI CARICO ALMENO 10 MINUTI PRIMA',55,214,9,true,blue);
  text("Controllare eventuali aggiornamenti comunicati dall'organizzazione.",55,196,9,false,navy);
  text('DELGROSSO VIAGGI & LIMOUSINE BUS',55,180,9,true,navy);
  line(45,124,550,124);
  text('Documento riservato al cliente - data generazione '+new Date().toISOString().slice(0,10),45,106,9,false,muted);
  text('San Severo · Archivio gestionale interno',45,90,9,false,muted);
  const stream=commands.join('\n')+'\n';
  const logoBinary=atob(LOGO_B64);
  const objs=[];let pdf='%PDF-1.4\n%'+meta+'\n';
  const put=(obj)=>{objs.push(pdf.length);pdf+=`${objs.length} 0 obj\n${obj}\nendobj\n`;};
  put('<< /Type /Catalog /Pages 2 0 R >>');
  put('<< /Type /Pages /Kids [3 0 R] /Count 1 >>');
  put('<< /Type /Page /Parent 2 0 R /MediaBox [0 0 595 842] /Resources << /Font << /F1 4 0 R /F2 5 0 R >> /XObject << /Im1 6 0 R >> >> /Contents 7 0 R >>');
  put('<< /Type /Font /Subtype /Type1 /BaseFont /Helvetica >>');
  put('<< /Type /Font /Subtype /Type1 /BaseFont /Helvetica-Bold >>');
  put(`<< /Type /XObject /Subtype /Image /Width ${LOGO_W} /Height ${LOGO_H} /ColorSpace /DeviceRGB /BitsPerComponent 8 /Filter /DCTDecode /Length ${logoBinary.length} >>\nstream\n${logoBinary}\nendstream`);
  put(`<< /Length ${stream.length} >>\nstream\n${stream}endstream`);
  if(pdf.length<2000)pdf+='%'+'.'.repeat(2000-pdf.length)+'\n';
  const xref=pdf.length;pdf+=`xref\n0 ${objs.length+1}\n0000000000 65535 f \n`;
  for(const pos of objs)pdf+=`${String(pos).padStart(10,'0')} 00000 n \n`;
  pdf+=`trailer\n<< /Size ${objs.length+1} /Root 1 0 R >>\nstartxref\n${xref}\n%%EOF\n`;
  return {ascii:pdf,base64:btoa(pdf),length:pdf.length,meta};
 }
 global.DGConfirmCore=Object.freeze({makePdf,seats});
})(window);
